const makingUpFakeNumbers = (a, b, c) =>
  Math.round(a * (b + c)).toLocaleString("en-US");

const Table = ({ columns }) => {
  let year = 2024;
  const arr = new Array(columns)
    .fill(null)
    .map((v, i) => year - i)
